import math
def out_valid(n,k,s,p=0):
    return (n + 2*p - k)//s + 1
def out_same(n,s):
    return math.ceil(n/s)
cases=[(32,3,1),(32,3,2),(224,3,2),(224,7,2),(13,3,1),(225,3,2)]
print("n    k  s | valid  same")
for n,k,s in cases:
    v=out_valid(n,k,s); sm=out_same(n,s)
    print(f"  {n:4d} {k:2d} {s:1d} | {v:5d}  {sm:4d}")
print("说明: same=ceil(n/s); 当 n 不能整除 s 时 same != valid（如 225/2: valid=112 same=113）")
print("225 整除校验: valid=", out_valid(225,3,2), " same=", out_same(225,2))
